K=90
assert len(OPT_ROWS)==47
assert all(len(row)==91 for row in OPT_ROWS)
assert all(type(x) is int for row in OPT_ROWS for x in row)

def coefficients(rows):
    denominator=sum(F(x)*F(x) for row in rows for x in row)
    return [F(1)]+[
      2*sum(F(row[i])*F(row[i+k]) for row in rows for i in range(K+1-k))/denominator
      for k in range(1,K+1)]

b_opt=coefficients(OPT_ROWS)
# Normalized Fejer kernel |sum_{j=0}^K exp(ijx)|^2/(K+1).
b_fejer=[F(1)]+[F(2*(K+1-k),K+1) for k in range(1,K+1)]
bk=[F(1,10**8)*b_fejer[k]+F(10**8-1,10**8)*b_opt[k] for k in range(K+1)]
assert bk[0]==1
assert all(x>0 for x in bk[1:])
assert bk[1]>1
b1=bk[1]; b=sum(bk[1:]); B=F(443795,100000)

def sin_bounds(x,n=34):
    term=x; partial=term
    for k in range(n):
      term=-term*x*x/F((2*k+2)*(2*k+3)); partial+=term
    nxt=-term*x*x/F((2*n+2)*(2*n+3))
    return min(partial,partial+nxt),max(partial,partial+nxt)

def cos_bounds(x,n=34):
    term=F(1); partial=term
    for k in range(n):
      term=-term*x*x/F((2*k+1)*(2*k+2)); partial+=term
    nxt=-term*x*x/F((2*n+1)*(2*n+2))
    return min(partial,partial+nxt),max(partial,partial+nxt)

def root_bounds(x):
    sl,su=sin_bounds(x); cl,cu=cos_bounds(x)
    assert sl>0 and cl>0
    return sl*sl-b1+b1*x*cl/su, su*su-b1+b1*x*cu/sl

lo=F(1132671913,10**9); hi=F(1132671916,10**9)
assert 0<lo<hi<F(3,2) and hi*hi<2
flo=root_bounds(lo); fhi=root_bounds(hi)
assert flo[0]>0 and fhi[1]<0
cos_hi_lower,_=cos_bounds(hi)
target=F(38457,800)
lhs=F(9,16)*b*b*(b+1)*B*B
rhs=target**3*cos_hi_lower**6
assert lhs<rhs
print(json.dumps({
 "degree":90,"sum_of_squares_factors":47,"all_bk_positive":True,
 "b1_gt_1":True,"minimum_bk_index":min(range(1,91),key=lambda k:bk[k]),
 "minimum_bk_decimal":format(float(min(bk[1:])),".17g"),
 "theta_bracket":["1.132671913","1.132671916"],
 "R_strictly_below":"48.07125",
 "exact_cube_margin_decimal":format(float(rhs-lhs),".17g")},indent=2))
